import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp']
MAX_WIDTH = 4096
MAX_HEIGHT = 4096

def validate_dimensions(width, height):
    try:
        w, h = int(width), int(height)
        if 1 <= w <= MAX_WIDTH and 1 <= h <= MAX_HEIGHT:
            return w, h
    except (ValueError, TypeError):
        pass
    return None, None

def sanitize_format(fmt):
    fmt = fmt.lower().strip()
    if fmt in ALLOWED_FORMATS:
        return fmt
    return None

@app.route('/api/v2/images/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to specified format and dimensions."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    target_format = sanitize_format(request.form.get('format', 'png'))
    if not target_format:
        return jsonify({'error': 'Invalid format'}), 400

    width, height = validate_dimensions(
        request.form.get('width', '800'),
        request.form.get('height', '600')
    )
    if not width:
        return jsonify({'error': 'Invalid dimensions'}), 400

    # Save uploaded file
    input_path = tempfile.mktemp(suffix='.tmp')
    uploaded.save(input_path)

    output_path = tempfile.mktemp(suffix=f'.{target_format}')

    # Build conversion command using ImageMagick
    # The 'label' parameter allows custom text overlay
    label_text = request.form.get('watermark', '')

    # Construct command - note: dimensions and format are validated above
    cmd = f'convert {input_path} -resize {width}x{height}'

    if label_text:
        # Add watermark text overlay
        cmd += f' -gravity South -annotate +0+10 "{label_text}"'

    cmd += f' {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd='/tmp'
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr.decode()[:200]}), 500

        with open(output_path, 'rb') as f:
            image_data = f.read()

        return image_data, 200, {'Content-Type': f'image/{target_format}'}
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    finally:
        for p in [input_path, output_path]:
            try:
                os.unlink(p)
            except OSError:
                pass

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
